/** Un emoji, tracé en vectoriel à la résolution réelle de l'écran. */
export function Emoji({
  name,
  className = "",
}: {
  name: string;
  className?: string;
}) {
  return (
    <svg aria-hidden focusable="false" className={className}>
      <use href={`#e-${name}`} />
    </svg>
  );
}
